  if (day <= 2) return 'sunny' // 처음 이틀은 맑게 — 마을을 둘러보기 좋게
  const season = seasonOf(day)
  // 잔치 날은 맑게 — 한 해에 한 번뿐인 행사가 비로 사라지지 않도록
  if (festivalOf(day)) return 'sunny'
