function seedOf(c: Pick<Companion, 'name' | 'since' | 'kind'>, salt: string): number {
  let seed = 2166136261
  for (const char of `${c.name}:${c.since}:${c.kind}:${salt}`) seed = Math.imul(seed ^ char.charCodeAt(0), 16777619) >>> 0
  return seed
}

