  const windowRow = (t: Tile) => (spot === 'window' && tileAt(t.x, t.y - 1) === 'N' ? 0 : 1)
  const far = (t: Tile) => Math.abs(t.x - anchor.x) + Math.abs(t.y - anchor.y)
  candidates.sort((a, b) => windowRow(a) - windowRow(b) || far(a) - far(b) || a.y - b.y || a.x - b.x)
