  const seat = at ?? (place && SEAT_PLACES.includes(place) ? front : undefined)
  return { ...s, act: { kind, left: ACT_SECONDS[kind], total: ACT_SECONDS[kind], facing: seat ? 'down' : s.player.facing, ...(seat ? { at: seat } : {}) } }
