export function syncHome(s: Pick<GameState, 'homeLevel'> & Partial<Pick<GameState, 'flags' | 'romance' | 'room' | 'village' | 'map' | 'newland' | 'homeWalls'>>): void {
  // 지금 어느 지도에 있는가, 새 터의 입구가 열렸는가 (계획 20 작업 3)
