/** 예전 엮기·옮겨 적기로 한 장을 마칠 때 흐르는 분 — 필사와 같다 (계획 14: 넓은 책상·기록대는 빠르게 하지 않는 꾸미기 물건) */
export function bindMinutes(s: Pick<GameState, 'needs' | 'clock' | 'room' | 'inv'> & Partial<Pick<GameState, 'flags'>>): number {
