    const a = 0.25 + rng() * 0.4
    return { kind, t: 0, hits: 0, misses: 0, zone: [a, Math.min(1, a + 0.22 + e / 2)], flash: null }
  }
  return e ? { kind, items: [], got: 0, nextId: 1, spawn: 0, life: PICK_LIFE * (1 + e) } : { kind, items: [], got: 0, nextId: 1, spawn: 0 }
}

