export function noteNews(n: Notebook, npc: string, id: string, day: number): Notebook {
  const prev = n.news?.[npc]
  if (prev && prev.id === id && prev.day === day) return n
  if (prev && prev.day > day) return n
  return { ...n, news: { ...n.news, [npc]: { id, day } } }
}

