export const HALL_SPOTS: readonly Tile[] = (() => {
  const [t0] = PLACES.hallTable.tiles
  return [
    ...[0,1,2,3].map(dx=>({x:t0.x+dx,y:t0.y-1})),
    {x:t0.x-1,y:t0.y}, {x:t0.x+4,y:t0.y},
