export type TreeKind = 'deciduous' | 'fruit' | 'evergreen'

/** 봄에 꽃 피는 과일나무: 북쪽 풀밭 내 집 양옆 한 쌍, 광장 위쪽 귀퉁이 한 쌍 (큰길 가운데를 두고 대칭) */
export const FRUIT_TREES: readonly Tile[] = [
