export function childStage(c: Pick<Child, 'born'>, day: number): ChildStage {
  const age = day - c.born
  return age >= ADULT_AT ? 'adult' : age >= HELPER_AT ? 'helper' : age >= TODDLER_AT ? 'toddler' : 'baby'
}

/** 물려받는 타고난 값: 플레이어의 단계 4 이상 능력치 +1, 배우자 집안 능력치 +1, 한 능력치 최대 2 */
export function inheritBorn(player: Stats, spouseStat: StatId | undefined): Partial<Record<StatId, number>> {
  const out: Partial<Record<StatId, number>> = {}
  for (const id of STAT_IDS) if ((player[id]?.level ?? 1) >= 4) out[id] = 1
  if (spouseStat) out[spouseStat] = Math.min(2, (out[spouseStat] ?? 0) + 1)
  return out
}

/** 세 추가 후보의 옛 아이에게 빠졌던 배우자 유전 한 칸만 복원한다. lean이 있어 중복 지급하지 않는다. */
export function repairSpouseInheritance(c: Child | null, partner: string | null, spouseStat: StatId | undefined): Child | null {
  if (!c || c.lean !== null || !spouseStat || !partner || !['merchant', 'presser', 'postman'].includes(partner)) return c
  return { ...c, lean: spouseStat, stats: { ...c.stats, [spouseStat]: { ...c.stats[spouseStat], born: Math.min(2, c.stats[spouseStat].born + 1) } } }
}

/** 날 씨앗으로 아이의 모습과 첫 이름 */
export function newChild(day: number, player: Stats, spouseStat: StatId |

export function canShareClubDish(s: GameState, id: string): boolean {
  const run = sessionOf(s, id)
  const a = appt(s, id)
  return !!run && !!a && !!a.attended && canAttendAppt(s,id) && a.activity === 'tea' && run.step === 'activity' && !run.shared && clubDishes(s).length > 0
}
/** 만든 음식 하나를 차 모임에 나눈다: 가방에서 하나, 함께한 이웃마다 마음 +1, 함께 먹은 기억 */
export function shareClubDish(s: GameState, id: string, dish: ItemId): GameState {
  if (!canShareClubDish(s, id) || !COOKED_ITEMS.includes(dish) || count(s.inv, dish) < 1) return s
  const a = appt(s, id)!
  const run = sessionOf(s, id)!
  const inv = take(s.inv, { [dish]: 1 })
  if (!inv) return s
  let next: GameState = { ...s, inv, clubSessions: { ...s.clubSessions, [id]: { ...run, shared: dish } } }
  const with_ = a.startedWith ?? a.members ?? []
  for (const npc of with_) next = heartUp(next, npc, 1)
  if (with_.length) next = recordExperienceIn(next, { id: `clubMeal:${id}`, kind: 'meal', with: [...with_] })
  return next
}

/** 주민 근황에 함께하기: 그 소식을 꺼낸 이웃과 기억 하나, 마음 +2 — 모임마다 한 번 */
export function canJoinNews(s: GameState, id: string, npc: string): boolean {
  const run = sessionOf(s, id)
  const a = appt(s,id)
  return !!run && !run.join

export function canJoinNews(s: GameState, id: string, npc: string): boolean {
  const run = sessionOf(s, id)
  const a = appt(s,id)
  return !!run && !run.joinedNews && !!a?.attended && canAttendAppt(s,id) && (a.startedWith ?? []).includes(npc)
}
export function joinNews(s: GameState, id: string, npc: string): GameState {
  if (!canJoinNews(s, id, npc)) return s
  const run = sessionOf(s, id)!
  let next: GameState = { ...s, clubSessions: { ...s.clubSessions, [id]: { ...run, joinedNews: npc } } }
  next = heartUp(next, npc, 2)
  return recordExperienceIn(next, { id: `clubNews:${id}`, kind: 'club', with: [npc] })
}

export function canLeaveWork(s:GameState,clubId:string,place:PlaceId):boolean {
 const others=Object.entries(s.clubWorks??{}).filter(([id,w])=>id!==clubId && w.place===place && (s.clubs??[]).some(c=>c.id===id && c.active)).length
 return clubWorkTiles(s,place).length>others
}
export interface ClubWorkSpot {club:string; art:'cushionPattern'; color:string; place:PlaceId; at:Tile}
/** 지금 모임 자리에 놓여 있는 작품 — 해산한 모임·아직 짓지 않은 공동 시설의 작품은 보이지 않는다 */
export function clubWorkSpots(s:Pick<GameState,'clubs'|'clubWorks'|'shelved'|'flags'|'progress'>):ClubWorkSpot[] {
 const out:ClubWorkSpot[]=[],used:Record<string,number>={}
 const built=new Set(builtIds(s.flags).map(id=>SITES[id].place))
 const ids=Object.keys(s.clubWorks??{}).sort((a,b)=>(Number(a.split(':')[1])||0)-(Number(b.split(':')[1])||0))
 for(const club of ids) {
  const w=s.clubWorks[club]
  if(!(s.clubs??[]).some(c=>c.id===club && c.active) || !CLUB_PLACES.includes(w.place) || (FACILITY_PLACES.includes(w.place as never) && !built.has(w.place as never))) continue
  const at=clubWorkTiles(s,w.place)[used[w.place]??0]
  used[w.place]=(used[w.place]??0)+1
  if(at) out.push({club,art:'cushionPattern',color:w.color,place:w.pl

export function canCook(s: GameState, dish: DishId): CookBlock {
  const def = DISHES[dish]
  if (dish === 'bread') return null
  const access = featureAccess(s, 'cooking')
  if (access === 'locked' || (access === 'preview' && dish !== 'herbTea')) return 'locked'
  if (cookOf(s).run) return 'busy'
  if (!knownDish(s, dish) && !(access === 'preview' && dish === 'herbTea')) return 'unknown'
  if (exhausted(s.needs)) return 'tired'
  if (!haveStock(s, def.needs)) return 'needs'
  if (overflows(useStock(s, def.needs)!, { [def.item]: def.qty })) return 'full'
  return null
}
/** 모자란 재료 (안내용) */
export function missingFor(s: GameState, dish: DishId): { item: ItemId; need: number; have: number }[] {
  return (Object.entries(DISHES[dish].needs) as [ItemId, number][]).map(([item, need]) => ({ item, need, have: count(s.inv, item) + count(s.chest ?? {}, item) })).filter(m => m.have < m.need)
}

/** 시작: 재료를 한 번 쓰고 손질부터. 이미 시작했으면 그대로 */
export function startCook(s: GameState, dish: DishId, rng: Rng): GameState {
  if (canCook(s, dish) || dish === 'bread') return s
  const def = DISHES[dish]
  const paid = useStock(s, def.needs)!
  const uneven = mulberry32(s.clock.day * 97

export function canEatDish(s: GameState, item: ItemId): EatBlock {
  if (!COOKED_ITEMS.includes(item)) return 'notFood'
  return count(s.inv, item) > 0 ? null : 'none'
}
function eatEffect(s: GameState, item: ItemId, shared: boolean): GameState {
  const tea = item === 'herbTea'
  const hunger = Math.max(0, s.needs.hunger - (DISH_HUNGER[item] ?? 0))
  return {
    ...s,
    needs: { ...s.needs, hunger },
    flags: { ...s.flags, mealDay: s.clock.day, ...(shared ? { sharedMealDay: s.clock.day } : {}), ...(tea ? {} : { ateDay: s.clock.day }) },
  }
}
/** 혼자 먹기·마시기: 가방에서 한 접시. 시간이 조금 흐르고 그날 기분이 조금 좋아진다 */
export function eatDish(s: GameState, item: ItemId): GameState {
  if (canEatDish(s, item)) return s
  const tea = item === 'herbTea'
  const next = eatEffect({ ...s, inv: take(s.inv, { [item]: 1 })! }, item, false)
  const eating = startAct(passTime(next, tea ? TEA_MINUTES : EAT_MINUTES), tea ? 'drink' : 'eat')
  return tea ? eating : { ...eating, player: { ...eating.player, path: [] }, act: { ...eating.act!, food: item } }
}

// ── 식탁 ──
/** 식탁이 되는 자리: 정해 둔 차 자리(탁자 + 앉을 곳) */
export function diningSpaces(s: Pick<GameState, 'room' | 'spaces' | 'homeLevel' | '

export function canServe(s: GameState): ServeBlock {
  if (featureAccess(s, 'cooking') === 'locked') return 'locked'
  syncHome(s)
  if (!isHome(playerTile(s))) return 'away'
  if (!diningSpaces(s).length) return 'noSpace'
  if (cookOf(s).table) return 'busy'
  if (!COOKED_ITEMS.some(i => count(s.inv, i) > 0)) return 'noFood'
  return null
}
/** 차릴 수 있는 접시 수: 가진 만큼, 자리 수·넷까지 */
export function serveMax(s: GameState, item: ItemId): number {
  const sp = diningSpaces(s)[0]
  return sp ? Math.min(TABLE_MAX, tableCapacity(s, sp), count(s.inv, item)) : 0
}
/** 식탁에 차린다: 가방의 접시를 식탁 회차 재고로 한 번 옮긴다 (먹기·치우기 한 곳에서만 쓴다) */
export function serveTable(s: GameState, item: ItemId, n: number): GameState {
  if (canServe(s) || !COOKED_ITEMS.includes(item) || !Number.isInteger(n) || n < 1 || n > serveMax(s, item)) return s
  const sp = diningSpaces(s)[0]
  const c = cookOf(s)
  const table: TableMeal = { id: `table:${c.meals + 1}`, day: s.clock.day, item, left: n, space: sp.id, ate: [] }
  return withCooking({ ...s, inv: take(s.inv, { [item]: n })! }, { table, meals: c.meals + 1 })
}
/** 식탁이 아직 쓸 수 있는가 (날이 바뀌었거나 가구가 옮겨져 자리가 없어졌으면 아니다) */
