export function wayOdds(level: number): [number, number, number] {
  if (level <= 2) return [100, 0, 0]
  if (level <= 4) return [80, 20, 0]
  if (level <= 6) return [55, 30, 15]
  if (level <= 8) return [40, 30, 30]
